import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allowlist for sort columns - but note: user input for filter is NOT parameterized
    private static final Pattern SORT_PATTERN = Pattern.compile("^(name|date|amount|status)$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String sessionUser = (String) req.getSession().getAttribute("username");
        if (sessionUser == null) {
            resp.sendError(401);
            return;
        }

        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String filterExpr = req.getParameter("filter");

        // Validate sort column against allowlist
        if (sortCol == null || !SORT_PATTERN.matcher(sortCol).matches()) {
            sortCol = "date";
        }

        // "Sanitization" that is actually bypassable
        if (filterExpr != null) {
            // Remove obvious SQL keywords - easily bypassed with case mixing or inline comments
            filterExpr = filterExpr.replaceAll("(?i)(union|select|drop|insert|update|delete|;|--)", "");
        }

        StringBuilder query = new StringBuilder();
        query.append("SELECT id, name, date, amount, status FROM reports WHERE department = '");
        query.append(department != null ? department.replace("'", "''") : "general");
        query.append("' AND owner = '").append(sessionUser.replace("'", "''")).append("'");

        // The filter expression is concatenated directly - the keyword filter above is trivially bypassed
        if (filterExpr != null && !filterExpr.trim().isEmpty()) {
            query.append(" AND (").append(filterExpr).append(")");
        }

        query.append(" ORDER BY ").append(sortCol).append(" DESC LIMIT 100");

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": %d, \"name\": \"%s\", \"date\": \"%s\", \"amount\": %.2f, \"status\": \"%s\"}",
                    rs.getInt("id"),
                    StringEscapeUtils.escapeJson(rs.getString("name")),
                    rs.getString("date"),
                    rs.getDouble("amount"),
                    StringEscapeUtils.escapeJson(rs.getString("status")));
            }
            out.print("\n]");

        } catch (SQLException e) {
            // Leak error details - useful for blind SQLi confirmation
            out.print("{\"error\": \"" + StringEscapeUtils.escapeJson(e.getMessage()) + "\"}");
            resp.setStatus(500);
        }
    }
}
